const sunLight = new THREE.DirectionalLight('#fff0cb',3.3); sunLight.position.set(-85,125,-50); sunLight.castShadow=true; sunLight.shadow.mapSize.set(2048,2048); sunLight.shadow.camera.left=-160; sunLight.shadow.camera.right=160; sunLight.shadow.camera.top=160; sunLight.shadow.camera.bottom=-160; sunLight.shadow.bias=-.0002; scene.add(sunLight);
