// Soft distant cloud puffs frame the island, not the racing line.
function cloud(x,y,z,s){const g=new THREE.Group(); for(let i=0;i<5;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(s*(.55+Math.sin(i*3+1)*.12),12,9),new THREE.MeshBasicMaterial({color:'#fff8e9',transparent:true,opacity:.72}));m.position.set((i-2)*s*.5,Math.sin(i*4)*s*.13,Math.cos(i*2)*s*.1);g.add(m)}g.position.set(x,y,z);world.add(g);return g}
