const sunOrb = new THREE.Mesh(new THREE.SphereGeometry(12,24,16),new THREE.MeshBasicMaterial({color:'#ffe2a1'})); sunOrb.position.set(-145,94,-210); world.add(sunOrb);

// Closed, sculpted coastline course. Catmull-Rom gives a broad, flowing arcade circuit.
const anchors=[
