import fs from 'node:fs/promises';
const pages = await (await fetch('http://127.0.0.1:9222/json')).json();
const page = pages.find(x => x.type === 'page');
if (!page) throw new Error('No Chrome page target');
const ws = new WebSocket(page.webSocketDebuggerUrl);
let nextId = 0;
const pending = new Map();
const events = [];
ws.addEventListener('message', event => {
  const data = JSON.parse(event.data);
  if (data.id && pending.has(data.id)) { pending.get(data.id)(data); pending.delete(data.id); }
  if (data.method === 'Runtime.exceptionThrown' || (data.method === 'Runtime.consoleAPICalled' && ['error','warning'].includes(data.params.type))) events.push(data);
});
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, {once:true}); ws.addEventListener('error', reject, {once:true}); });
function call(method, params={}) { const id=++nextId; ws.send(JSON.stringify({id,method,params})); return new Promise(resolve=>pending.set(id,resolve)); }
await call('Page.enable'); await call('Runtime.enable');
await call('Emulation.setDeviceMetricsOverride',{width:1280,height:720,deviceScaleFactor:1,mobile:false});
await new Promise(r=>setTimeout(r,3000));
const state = await call('Runtime.evaluate',{expression:'({title:document.title, canvas:!!document.querySelector("canvas"), start:document.getElementById("startOverlay")?.className, body:document.body.innerText.slice(0,100)})',returnByValue:true});
const shot = await call('Page.captureScreenshot',{format:'jpeg',quality:82,fromSurface:true});
await fs.writeFile('/tmp/opencode/sunset-check.jpg',Buffer.from(shot.result.data,'base64'));
console.log('PAGE',state.result.result.value);
console.log('CAPTURED /tmp/opencode/sunset-check.jpg');
console.log('BROWSER_EVENTS',JSON.stringify(events.map(e=>e.method==='Runtime.exceptionThrown'?e.params.exceptionDetails.text:e.params.args?.map(a=>a.value).join(' '))));
ws.close();

